/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

extern f32 gModeParamTable;

/* Returns the mode's first table parameter (1.0 for mode 0x24) divided by 8, as a byte. */ s32 getModeParamEighth(s32 modeIndex) {
    f32 scaledParam;
    f32 param;
    s32 result;

    param = *(&gModeParamTable + modeIndex * 0x3a);
    if (modeIndex == 0x24) {
        param = 1.0f;
    }
    scaledParam = param * 0.125f;
    result = (u32) scaledParam;
    return result & 0xFF;
}
